tool_config = {"tools": [{"toolSpec": {
  "name": "search_matter_docs",
  "description": "Full-text search within ONE matter. Returns up to 20 hits.",
  "inputSchema": {"json": {
    "type": "object",
    "properties": {
      "matter_id": {"type": "string", "pattern": "^M-[0-9]{6}$"},
      "query": {"type": "string", "maxLength": 500}},
    "required": ["matter_id", "query"],
    "additionalProperties": False}}}}]}

resp = bedrock.converse(modelId=MODEL, messages=msgs, toolConfig=tool_config)
if resp["stopReason"] == "tool_use":
    for block in resp["output"]["message"]["content"]:
        if "toolUse" in block:
            call = block["toolUse"]
            try:
                args = SearchArgs.model_validate(call["input"])   # pydantic
                result = {"toolUseId": call["toolUseId"],
                          "content": [{"json": run_search(args)}]}
            except ValidationError as e:
                result = {"toolUseId": call["toolUseId"], "status": "error",
                          "content": [{"text": f"Invalid arguments: {e}"}]}
            msgs.append({"role": "user", "content": [{"toolResult": result}]})

