from bedrock_agentcore import BedrockAgentCoreApp
app = BedrockAgentCoreApp()          # serves POST /invocations and GET /ping on :8080

@app.entrypoint
def handle(payload, context):
    # context.session_id == runtimeSessionId -> one microVM per session
    return graph.invoke({"messages": [payload["prompt"]]},
                        {"configurable": {"thread_id": context.session_id}})

if __name__ == "__main__":
    app.run()

